void b1dma_reset_ctr ( struct capi_ctr * ctrl ) { avmctrl_info * cinfo = ( avmctrl_info * ) ( ctrl -> driverdata ) ; avmcard * card = cinfo -> card ; unsigned long flags ; spin_lock_irqsave ( & card -> lock , flags ) ; b1dma_reset ( card ) ; memset ( cinfo -> version , 0 , sizeof ( cinfo -> version ) ) ; spin_unlock_irqrestore ( & card -> lock , flags ) ; capi_ctr_down ( ctrl ) ; } 